function flipsToZero(n: number): number {
  const dist = new Map<number, number>([[n, 0]]);
  const queue = [n];
  for (let head = 0; head < queue.length; head++) {
    const x = queue[head], d = dist.get(x)!;
    if (x === 0) return d;
    const moves = [x ^ 1, x ^ ((x & -x) << 1)];
    for (const y of moves) {
      if (!dist.has(y)) { dist.set(y, d + 1); queue.push(y); }
    }
  }
  return -1;
}

