class Solution:
    def flipsToZero(self, n: int) -> int:
        dist = {n: 0}
        queue = deque([n])
        while queue:
            x = queue.popleft()
            if x == 0:
                return dist[x]
            for y in (x ^ 1, x ^ ((x & -x) << 1)):
                if y not in dist:
                    dist[y] = dist[x] + 1
                    queue.append(y)
        return -1

